-- Portable SQL: text UUIDs, numeric specs, no SQLite-specific row IDs or JSON types.
CREATE TABLE IF NOT EXISTS ingredients (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS malt_specs (ingredient_id TEXT PRIMARY KEY REFERENCES ingredients(id), maltster TEXT, type TEXT NOT NULL, lovibond REAL NOT NULL, ebc REAL NOT NULL, ppg REAL NOT NULL, extract_percent REAL NOT NULL, diastatic_power REAL, requires_mash BOOLEAN NOT NULL, max_percent REAL NOT NULL, fermentability_notes TEXT NOT NULL, body_contribution TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hop_specs (ingredient_id TEXT PRIMARY KEY REFERENCES ingredients(id), origin TEXT NOT NULL, purpose TEXT NOT NULL, alpha_min REAL NOT NULL, alpha_max REAL NOT NULL, beta_min REAL, beta_max REAL, cohumulone REAL, total_oil REAL, oils TEXT NOT NULL, substitutes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS yeast_specs (ingredient_id TEXT PRIMARY KEY REFERENCES ingredients(id), lab TEXT NOT NULL, code TEXT NOT NULL, form TEXT NOT NULL, type TEXT NOT NULL, attenuation_min REAL, attenuation_max REAL, flocculation TEXT NOT NULL, temp_min_c REAL, temp_max_c REAL, alcohol_tolerance REAL, pof BOOLEAN, diastaticus BOOLEAN);
CREATE TABLE IF NOT EXISTS vocabulary (id TEXT PRIMARY KEY, parent TEXT NOT NULL, label TEXT NOT NULL, axis BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS flavor_descriptors (id TEXT PRIMARY KEY, ingredient_id TEXT NOT NULL REFERENCES ingredients(id), descriptor TEXT NOT NULL REFERENCES vocabulary(id), intensity REAL NOT NULL CHECK(intensity>=0 AND intensity<=5), usage_context TEXT NOT NULL, context TEXT NOT NULL, source_type TEXT NOT NULL, confidence TEXT NOT NULL, note TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipes (id TEXT PRIMARY KEY, name TEXT NOT NULL, document TEXT NOT NULL, updated_at TEXT NOT NULL, owner_id TEXT, visibility TEXT NOT NULL DEFAULT 'private' CHECK (visibility IN ('private','public')));
CREATE TABLE IF NOT EXISTS brew_logs (id TEXT PRIMARY KEY, recipe_id TEXT NOT NULL, date TEXT NOT NULL, document TEXT NOT NULL, owner_id TEXT);
CREATE TABLE IF NOT EXISTS additive_specs (ingredient_id TEXT PRIMARY KEY REFERENCES ingredients(id), category TEXT NOT NULL, form TEXT NOT NULL, stages TEXT NOT NULL, usage_guide TEXT NOT NULL);
